question.text:
Kết quả sau khi chạy chương trình C++ sau là:
```cpp
#include <iostream>
#define MAX(x, y) ((x) > (y) ? (x) : (y))
using namespace std;
int main() {
    int a = 0;
    int b = 1;
    int c = MAX(a++, b--);
    cout << c;
    return 0;
}
```

Cho biết kết quả khi chạy chương trình C sau:
```c
#include<stdio.h>
int f(int a, int b) {
    return b+a;
}
int main() {
    int j,i[5] = {10,12,14,16,18}, *p,*q;
    p=i; q=p;
    *q= f(i[0], *p++);
    printf("%d %d \n", *p, *q);
    return 0;
}
```

Cho biết dòng kết quả thứ 3 khi chạy chương trình sau:
```cpp
#include<iostream>
using namespace std;
template <typename T>
T maxval(T x, T y){
    static int count=0;
    cout << ++count << ", ";
    return (x > y) ? x : y;
}
int main() {
    int i = maxval(3, 7);
    cout << i << endl;
    double d = maxval(6.34, 18.523);
    cout << d << endl;
    d = maxval(16.34, 28.523);
    cout << d << endl;
    // ...
    return 0;
}
```

Kết quả sau khi chạy chương trình C++ sau là:
```cpp
#include <iostream>
using namespace std;
int main() {
    char s[6]="xyz";
    char * const ptr2 = s;
    s[1] = 'Y';
    *(ptr2+1) += 1;
    ptr2 += 1;
    cout << ptr2;
    return 0;
}
```
